            code: `const form = {
  email: '',

  set email(value) {
    const clean = String(value).trim().toLowerCase()
    if (!clean.includes('@')) return   // refuse, leave the old value
    this._email = clean                // the real field
  },

  get email() {
    return this._email || ''
  },

  get domain() {
    return this.email.split('@')[1] || ''   // derived, nothing to store
  }
}`
